class PlainResultList extends Array {
  static get [Symbol.species]() {
    return Array;
  }
}

const a = PlainResultList.from([1, 2, 3, 4]);
const evens = a.filter((n) => n % 2 === 0);

console.log(a instanceof PlainResultList);
console.log(evens instanceof PlainResultList);
console.log(evens.join(","));
